// --- Domain Types & Enums ---

export type AccountGroupType =
  | 'CHECKING'
  | 'SAVINGS'
  | 'CREDITCARD'
  | 'LOAN'
  | 'LINEOFCREDIT'
  | 'BROKERAGE'
  | 'RETIREMENT';

export type SelectionMode = AccountGroupType | 'ALL';

// --- Core Data Interfaces ---

export interface GroupBalance {
  localCurrencyCode?: string;
  localCurrencyBalanceAmount?: number;
}

export interface AccountDetail {
  id: string;
  accountNumber: string;
  accountName: string;
  balance: GroupBalance;
  status: 'ACTIVE' | 'PENDING' | 'CLOSED';
}

export interface AccountGroupDetails {
  accountGroup: AccountGroupType;
  checkingAccountsDetails?: AccountDetail[];
  savingsAccountsDetails?: AccountDetail[];
  creditCardAccountsDetails?: AccountDetail[];
  loanAccountsDetails?: AccountDetail[];
  lineOfCreditAccountsDetails?: AccountDetail[];
  brokerageAccountsDetails?: AccountDetail[];
  retirementAccountsDetails?: AccountDetail[];
  totalCurrentBalance?: GroupBalance;
  totalAvailableBalance?: GroupBalance;
}

// --- Component Props & State ---

export interface AccountGroupSelectorProps {
  groups: AccountGroupDetails[];
  selectedGroup: SelectionMode;
  onSelectGroup: (group: SelectionMode) => void;
  className?: string;
  isLoading?: boolean;
  error?: string | null;
}

// --- Configuration & Constants ---

export interface GroupConfig {
  label: string;
  colorClass: string;
  activeColorClass: string;
  icon: React.ReactNode;
}

